from heapq import heappush, heappop

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Priority queue to store paths, starting with each cell
    pq = []
    for i in range(N):
        for j in range(N):
            heappush(pq, (grid[i][j], [(i, j)]))

    # Perform BFS with priority queue
    while pq:
        value, path = heappop(pq)
        if len(path) == k:
            return [grid[x][y] for x, y in path]

        x, y = path[-1]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                new_path = path + [(nx, ny)]
                new_value = value + grid[nx][ny]
                heappush(pq, (new_value, new_path))
```

