def tri(n):
    if n < 0:
        return []

    # Initialize the sequence with base cases
    sequence = [0] * (n + 1)
    sequence[0] = 1  # tri(0) is not defined in the problem, but we start from 0 for indexing
    sequence[1] = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            sequence[i] = 1 + i // 2
        else:
            if i == 1:
                sequence[i] = 3
            else:
                sequence[i] = sequence[i - 1] + sequence[i - 2] + (sequence[i + 1] if i + 1 <= n else 0)

    return sequence
