        start = 0
        while start < k:
            sublist[start], sublist[k] = sublist[k], sublist[start]
            start += 1
            k -= 1

    n = len(arr)
    for size in range(n, 1, -1):
        max_index = arr.index(max(arr[:size]))
        if max_index != size - 1:
            if max_index != 0:
                flip(arr, max_index)
            flip(arr, size - 1)
