def first(arr, low, high, x, n):
    if high >= low:
        mid = low + (high - low) // 2

        # Check if mid is the first occurrence of x
        if (mid == 0 or arr[mid - 1] != x) and arr[mid] == x:
            return mid
        elif arr[mid] < x:
