def max_sub_array_sum_repeated(arr, n, k):
    max_so_far = arr[0]
    max_ending_here = arr[0]
    for i in range(1, n):
        max_ending_here = max(arr[i], max_ending_here + arr[i])
        max_so_far = max(max_so_far, max_ending_here)
    max_prefix_sum = arr[0]
    max_suffix_sum = arr[0]
    prefix_sum = arr[0]
    suffix_sum = arr[0]
    for i in range(1, n):
        prefix_sum += arr[i]
        max_prefix_sum = max(max_prefix_sum, prefix_sum)
    for i in range(n-2, -1, -1):
        suffix_sum += arr[i]
        max_suffix_sum = max(max_suffix_sum, suffix_sum)
    total_sum = sum(arr)
    if k == 1:
        return max_so_far
    if total_sum > 0:
        return max(max_so_far, max_prefix_sum + max_suffix_sum + (k-2) * total_sum)
    else:
        return max(max_so_far, max_prefix_sum + max_suffix_sum)
