def check_expression(expression):
    stack = []
    opening_brackets = "({["
    closing_brackets = ")}]"
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return not stack
```

